<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#201b25;font-size:12px}header{display:flex;justify-content:space-between;border-bottom:3px solid {{ $invoice->workspace->branding?->primary_colour ?? '#ff6b35' }};padding-bottom:22px}h1{font-size:30px;margin:0}.brand{color:{{ $invoice->workspace->branding?->primary_colour ?? '#ff6b35' }};font-weight:bold}.workspace-logo{max-width:160px;max-height:58px;margin-bottom:8px}.meta{margin:28px 0;line-height:1.7}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #ddd;text-align:left}th{background:#f6f3f1}.right{text-align:right}.totals{margin:25px 0 0 auto;width:300px;border:1px solid #ccc;page-break-inside:avoid}.totals td{padding:11px 14px;border:1px solid #ccc}.totals td:last-child{text-align:right;white-space:nowrap}.total{font-size:16px;font-weight:bold;background:#f6f3f1}footer{position:fixed;bottom:0;color:#777;font-size:9px}</style></head><body><header><div>@if($invoice->workspace->branding?->logo_path)<img class="workspace-logo" src="{{ public_path('storage/'.$invoice->workspace->branding->logo_path) }}" alt="">@else<span class="brand">{{ $invoice->workspace->name }}</span>@endif<h1>Invoice</h1></div><div><strong>{{ $invoice->number }}</strong><br>Status: {{ ucfirst($invoice->status) }}</div></header><div class="meta"><strong>Bill to</strong><br>{{ $invoice->client->name }}<br>{{ $invoice->client->email }}<br>{!! nl2br(e($invoice->client->address)) !!}<br><br>Due: {{ $invoice->due_on?->format('d M Y') }}</div><table><thead><tr><th>Description</th><th>Time</th><th>Rate</th><th class="right">Amount</th></tr></thead><tbody>@foreach($invoice->lines as $line)<tr><td>{{ $line->description }}</td><td>{{ intdiv($line->quantity_minutes,60) }}h {{ $line->quantity_minutes%60 }}m</td><td>£{{ number_format($line->rate_minor/100,2) }}</td><td class="right">£{{ number_format($line->amount_minor/100,2) }}</td></tr>@endforeach</tbody></table><table class="totals"><tbody><tr><td>Subtotal</td><td><b>£{{ number_format($invoice->subtotal_minor/100,2) }}</b></td></tr><tr><td>Tax</td><td><b>£{{ number_format($invoice->tax_minor/100,2) }}</b></td></tr><tr class="total"><td>Total</td><td>£{{ number_format($invoice->total_minor/100,2) }}</td></tr></tbody></table><footer>{{ $invoice->workspace->branding?->email_footer ?: 'Generated securely by myhourspay' }} · {{ now()->format('d M Y H:i') }}</footer></body></html>
